    "inlineSchema": "generator client {\n  provider = \"prisma-client\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ============================================\n// Enums\n// ============================================\n\nenum Role {\n  ALUNO\n  COORDENADOR_CURSO\n  AVALIADOR\n  ADMIN\n}\n\nenum StatusInsc {\n  PENDENTE\n  CONFIRMADA\n  REJEITADA\n}\n\nenum StatusProva {\n  RASCUNHO\n  PUBLICADA\n  EM_ANDAMENTO\n  ENCERRADA\n}\n\nenum Medalha {\n  OURO\n  PRATA\n  BRONZE\n}\n\nenum Eixo {\n  ALGEBRA\n  GEOMETRIA\n  ANALISE\n  ESTATISTICA\n  DIDATICA\n}\n\nenum Dificuldade {\n  FACIL\n  MEDIO\n  DIFICIL\n}\n\nenum StatusEnvioFase2 {\n  PENDENTE\n  ENVIADO\n  AVALIADO\n}\n\n// ============================================\n// Catalog models\n// ============================================\n\nmodel Instituicao {\n  id        String   @id @default(uuid())\n  nome      String\n  sigla     String   @unique\n  estado    String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  cursos     Curso[]\n  usuarios   User[]\n  inscricoes Inscricao[]\n}\n\nmodel Curso {\n  id            String      @id @default(uuid())\n  nome          String\n  instituicaoId String\n  instituicao   Instituicao @relation(fields: [instituicaoId], references: [id], onDelete: Cascade)\n  createdAt     DateTime    @default(now())\n  updatedAt     DateTime    @updatedAt\n\n  coordenadores CoordenadorCurso[]\n  usuarios      User[]\n  inscricoes    Inscricao[]\n\n  @@unique([nome, instituicaoId])\n}\n\n// ============================================\n// Auth / User\n// ============================================\n\nmodel User {\n  id             String       @id @default(uuid())\n  nome           String\n  email          String       @unique\n  cpf            String       @unique\n  senhaHash      String\n  role           Role         @default(ALUNO)\n  instituicaoId  String?\n  instituicao    Instituicao? @relation(fields: [instituicaoId], references: [id])\n  cursoId        String?\n  curso          Curso?       @relation(fields: [cursoId], references: [id])\n  matricula      String\n  comprovanteUrl String?\n  dataNascimento DateTime\n  createdAt      DateTime     @default(now())\n  updatedAt      DateTime     @updatedAt\n\n  inscricao      Inscricao?\n  coordenadorias CoordenadorCurso[]\n  avaliacoes     AvaliacaoFase2[]\n  auditLogs      AuditLog[]\n}\n\nmodel CoordenadorCurso {\n  id      String @id @default(uuid())\n  userId  String @unique\n  cursoId String\n\n  user  User  @relation(fields: [userId], references: [id], onDelete: Cascade)\n  curso Curso @relation(fields: [cursoId], references: [id], onDelete: Cascade)\n}\n\n// ============================================\n// Edition\n// ============================================\n\nmodel Edicao {\n  id         String    @id @default(uuid())\n  ano        Int       @unique\n  titulo     String\n  status     String    @default(\"PLANEJAMENTO\")\n  dataInicio DateTime?\n  dataFim    DateTime?\n  pesoFase1  Float     @default(0.5)\n  pesoFase2  Float     @default(0.5)\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n\n  provas     Prova[]\n  inscricoes Inscricao[]\n}\n\n// ============================================\n// Enrollment\n// ============================================\n\nmodel Inscricao {\n  id             String     @id @default(uuid())\n  userId         String     @unique\n  edicaoId       String\n  user           User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  edicao         Edicao     @relation(fields: [edicaoId], references: [id])\n  status         StatusInsc @default(PENDENTE)\n  estado         String\n  municipio      String?\n  instituicaoId  String\n  cursoId        String\n  periodo        Int?\n  comprovanteUrl String?\n  fase1Nota      Float?\n  fase1Inicio    DateTime?\n  fase1Fim       DateTime?\n  fase2Tema      String?\n  notaFinal      Float?\n  medalha        Medalha?\n  createdAt      DateTime   @default(now())\n  updatedAt      DateTime   @updatedAt\n\n  instituicao Instituicao      @relation(fields: [instituicaoId], references: [id])\n  curso       Curso            @relation(fields: [cursoId], references: [id])\n  respostas   Resposta[]\n  enviosFase2 EnvioFase2[]\n  avaliacoes  AvaliacaoFase2[]\n\n  @@unique([userId, edicaoId])\n}\n\n// ============================================\n// Exam\n// ============================================\n\nmodel Prova {\n  id             String      @id @default(uuid())\n  edicaoId       String\n  fase           Int\n  titulo         String\n  duracaoMinutos Int\n  status         StatusProva @default(RASCUNHO)\n  publicadaEm    DateTime?\n  janelaInicio   DateTime?\n  janelaFim      DateTime?\n  versao         Int         @default(1)\n  createdBy      String\n  createdAt      DateTime    @default(now())\n  updatedAt      DateTime    @updatedAt\n\n  edicao    Edicao         @relation(fields: [edicaoId], references: [id])\n  questoes  ProvaQuestao[]\n  respostas Resposta[]\n}\n\nmodel Questao {\n  id           String      @id @default(uuid())\n  enunciado    String\n  alternativaA String\n  alternativaB String\n  alternativaC String\n  alternativaD String\n  alternativaE String\n  correta      String\n  eixo         Eixo\n  dificuldade  Dificuldade\n  createdBy    String?\n  createdAt    DateTime    @default(now())\n  updatedAt    DateTime    @updatedAt\n\n  provas    ProvaQuestao[]\n  respostas Resposta[]\n}\n\nmodel ProvaQuestao {\n  id        String @id @default(uuid())\n  provaId   String\n  questaoId String\n  ordem     Int\n\n  prova   Prova   @relation(fields: [provaId], references: [id], onDelete: Cascade)\n  questao Questao @relation(fields: [questaoId], references: [id], onDelete: Cascade)\n\n  @@unique([provaId, questaoId])\n  @@unique([provaId, ordem])\n}\n\nmodel Resposta {\n  id                 String   @id @default(uuid())\n  inscricaoId        String\n  provaId            String\n  questaoId          String\n  alternativaMarcada String\n  correta            Boolean  @default(false)\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n\n  inscricao Inscricao @relation(fields: [inscricaoId], references: [id], onDelete: Cascade)\n  prova     Prova     @relation(fields: [provaId], references: [id])\n  questao   Questao   @relation(fields: [questaoId], references: [id], onDelete: Cascade)\n\n  @@unique([inscricaoId, provaId, questaoId])\n}\n\n// ============================================\n// Phase 2\n// ============================================\n\nmodel EnvioFase2 {\n  id          String           @id @default(uuid())\n  inscricaoId String\n  tipo        String\n  arquivoUrl  String\n  status      StatusEnvioFase2 @default(PENDENTE)\n  enviadoEm   DateTime         @default(now())\n\n  inscricao Inscricao @relation(fields: [inscricaoId], references: [id], onDelete: Cascade)\n}\n\nmodel AvaliacaoFase2 {\n  id          String   @id @default(uuid())\n  inscricaoId String\n  avaliadorId String\n  nota        Float\n  parecer     String?\n  avaliadoEm  DateTime @default(now())\n\n  inscricao Inscricao @relation(fields: [inscricaoId], references: [id], onDelete: Cascade)\n  avaliador User      @relation(fields: [avaliadorId], references: [id])\n\n  @@unique([inscricaoId, avaliadorId])\n}\n\n// ============================================\n// Ranking & Audit\n// ============================================\n\nmodel RankingSnapshot {\n  id          String    @id @default(uuid())\n  edicaoId    String\n  estado      String?\n  dados       Json\n  publicadoEm DateTime?\n  createdAt   DateTime  @default(now())\n}\n\nmodel AuditLog {\n  id         String   @id @default(uuid())\n  actorId    String\n  acao       String\n  entidade   String\n  entidadeId String\n  payload    Json?\n  createdAt  DateTime @default(now())\n\n  actor User @relation(fields: [actorId], references: [id])\n}\n",
